#[test]
fn extmath_language_instantiates() {
    let lang = ExtMathLanguage;
    assert_eq!(lang.name(), "ExtMath");
}

#[test]
fn extmath_metadata_populated() {
    let lang = ExtMathLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_extmath_num_add() {
    mettail_runtime::clear_var_cache();
    let term = Num::Add(Box::new(Num::NumLit(0i32)), Box::new(Num::NumLit(0i32)));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for Add");
    if let Ok(parsed) = Num::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(displayed, re_displayed,
            "Roundtrip failed for Add: {} != {}", displayed, re_displayed);
    }
}

